    const KINTONE_COND_FUNCTIONS = ['LOGINUSER', 'PRIMARY_ORGANIZATION', 'NOW', 'TODAY', 'YESTERDAY', 'TOMORROW', 'FROM_TODAY', 'THIS_WEEK', 'LAST_WEEK', 'NEXT_WEEK', 'THIS_MONTH', 'LAST_MONTH', 'NEXT_MONTH', 'THIS_YEAR', 'LAST_YEAR', 'NEXT_YEAR'];
