      if (act === 'new-conv-cancel') { const m = conv.state.messages.find(x => x.data?.kind === 'new-conv-choices'); if (m) conv.state.messages.splice(conv.state.messages.indexOf(m), 1); renderChat(); renderComposer(); return; }
